'use strict';
const $=id=>document.getElementById(id);
const rates={plastic:{min:5000,max:5500,limit:50,label:'Пластиковая колонна'},steel:{min:5000,max:7000,limit:150,label:'Стальная колонна'},double:{min:6000,max:7000,limit:180,label:'Сталь + пластик'},seamless:{min:6500,max:7500,limit:200,label:'Бесшовная сталь + пластик'}};
const money=n=>new Intl.NumberFormat('ru-RU').format(n);
let mode='calc',step=0,quizComplete=false;
const answers={place:'',usage:'',people:'',access:''};
const questions=[{key:'place',title:'Где находится ваш участок?',hint:'Населённого пункта достаточно. Точный адрес пока не нужен.'},{key:'usage',title:'Как планируете пользоваться водой?',options:['Жить в доме круглый год','Приезжать на дачу в сезон','Для строительства','Пока не определился']},{key:'people',title:'Сколько человек будет пользоваться водой?',options:['1–2 человека','3–4 человека','5 и более','Другое / пока не знаю']},{key:'access',title:'Как обстоят дела с заездом техники?',options:['Есть свободный широкий подъезд','Узкие ворота или мало места','Есть другие ограничения','Нужно оценить со специалистом']}];
function getEstimate(){const depth=Number($('depth').value),rate=rates[$('construction').value];return{depth,rate,valid:Number.isInteger(depth)&&depth>=10&&depth<=rate.limit,min:depth*rate.min,max:depth*rate.max};}
function updateCalc(){const e=getEstimate();$('depth-warning').hidden=e.valid;$('depth-warning').textContent=Number.isInteger(e.depth)&&e.depth>=10?`В опубликованном прайсе этот вариант указан до ${e.rate.limit} м. Выберите другую конструкцию или уточните решение у специалиста.`:'Укажите целую глубину от 10 до 200 метров.';$('estimate').textContent=e.valid?`${money(e.min)}–${money(e.max)} ₽`:'Нужно уточнение';$('formula').textContent=e.valid?`${e.depth} м × ${money(e.rate.min)}–${money(e.rate.max)} ₽/м`:'Для этих параметров не показываем неподтверждённую цену.';$('extras').replaceChildren();for(const[id,label]of[['pump','Насос и автоматика'],['house','Подводка воды в дом']]){if($(id).checked){const line=document.createElement('div');line.className='extra-line';const text=document.createElement('span');text.textContent=label;const cost=document.createElement('b');cost.textContent='Отдельная смета';line.append(text,cost);$('extras').append(line);}}}
$('depth').addEventListener('input',()=>{$('depth-range').value=$('depth').value;updateCalc();});$('depth-range').addEventListener('input',()=>{$('depth').value=$('depth-range').value;updateCalc();});['construction','pump','house'].forEach(id=>$(id).addEventListener('change',updateCalc));
function setMode(next){mode=next;for(const type of['calc','quiz']){$(`tab-${type}`).setAttribute('aria-selected',String(type===mode));$(`tab-${type}`).tabIndex=type===mode?0:-1;$(`${type}-panel`).hidden=type!==mode;$(`${type}-result-content`).hidden=type!==mode;}$('result-label').textContent=mode==='calc'?'БУРЕНИЕ / ПРИМЕР РАСЧЁТА':'ПОДБОР / ПАРАМЕТРЫ УЧАСТКА';if(mode==='quiz'){renderQuestion();renderQuizSummary();}}
['calc','quiz'].forEach(type=>{$(`tab-${type}`).addEventListener('click',()=>setMode(type));$(`tab-${type}`).addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'calc':e.key==='End'?'quiz':type==='calc'?'quiz':'calc';setMode(next);$(`tab-${next}`).focus();}});});
function startQuiz(){setMode('quiz');$('calculator').scrollIntoView({behavior:'smooth'});}
document.querySelectorAll('[data-start-quiz]').forEach(button=>button.addEventListener('click',startQuiz));
function renderQuestion(){const q=questions[step];$('quiz-step').textContent=`Вопрос ${step+1} из ${questions.length}`;$('progress-fill').style.width=`${(step+1)/questions.length*100}%`;$('quiz-back').hidden=step===0;$('quiz-next').textContent=step===questions.length-1?'Завершить подбор →':'Далее →';$('quiz-error').textContent='';const box=$('quiz-content');box.replaceChildren();const heading=document.createElement('h3');heading.textContent=q.title;box.append(heading);if(q.key==='place'){const label=document.createElement('label');label.className='field';label.textContent='Населённый пункт';const input=document.createElement('input');input.id='quiz-place';input.name='place';input.placeholder='Например, Всеволожск';input.maxLength=120;input.value=answers.place||$('location').value;input.required=true;label.append(input);const hint=document.createElement('p');hint.className='hint';hint.textContent=q.hint;box.append(label,hint);}else{const group=document.createElement('div');group.className='quiz-options';group.setAttribute('role','radiogroup');group.setAttribute('aria-label',q.title);q.options.forEach((option,i)=>{const label=document.createElement('label');label.className='quiz-choice';const input=document.createElement('input');input.type='radio';input.name=q.key;input.value=option;input.checked=answers[q.key]===option;input.required=true;const text=document.createElement('span');text.textContent=option;label.append(input,text);group.append(label);});box.append(group);}}
function saveStep(){const q=questions[step];const value=q.key==='place'?$('quiz-place').value.trim():$('quiz-form').querySelector(`input[name="${q.key}"]:checked`)?.value;if(!value){$('quiz-error').textContent='Выберите ответ, чтобы продолжить.';return false;}answers[q.key]=value;if(q.key==='place')$('location').value=value;renderQuizSummary();return true;}
$('quiz-form').addEventListener('submit',e=>{e.preventDefault();if(!saveStep())return;if(step<questions.length-1){step++;renderQuestion();}else{quizComplete=true;prepareLead();}});$('quiz-back').addEventListener('click',()=>{const q=questions[step];const value=q.key==='place'?$('quiz-place').value.trim():$('quiz-form').querySelector(`input[name="${q.key}"]:checked`)?.value;if(value)answers[q.key]=value;step=Math.max(0,step-1);renderQuestion();});
function renderQuizSummary(){const dl=$('quiz-summary');dl.replaceChildren();for(const[key,label]of[['place','Участок'],['usage','Использование'],['people','Пользователи'],['access','Подъезд']]){if(answers[key]){const dt=document.createElement('dt');dt.textContent=label;const dd=document.createElement('dd');dd.textContent=answers[key];dl.append(dt,dd);}}}
function summary(){if(mode==='quiz')return[['Использование',answers.usage],['Пользователи',answers.people],['Подъезд',answers.access]].filter(row=>row[1]).map(row=>row.join(': ')).join('\n')+'\nГлубину, конструкцию и стоимость нужно уточнить со специалистом.';const e=getEstimate();let s=`Предполагаемая глубина: ${$('depth').value} м\nКонструкция: ${e.rate.label}\n`;s+=e.valid?`Пример стоимости бурения: ${money(e.min)}–${money(e.max)} ₽\nРасчёт по опубликованному прайсу с отметкой «до конца 2019 года», не актуальная смета.`:'Стоимость: требуется индивидуальное уточнение.';if($('pump').checked)s+='\nДополнительно: насос и автоматика, стоимость уточнить.';if($('house').checked)s+='\nДополнительно: подводка воды в дом, стоимость уточнить.';return s;}
function prepareLead(){if(mode==='quiz'&&!quizComplete){$('quiz-error').textContent='Завершите четыре вопроса или заполните заявку ниже.';$('quiz-panel').scrollIntoView({behavior:'smooth'});return;}$('lead-summary').value=summary();$('request').scrollIntoView({behavior:'smooth'});$('location').focus({preventScroll:true});}
$('prepare-lead').addEventListener('click',prepareLead);document.querySelectorAll('[data-package]').forEach(button=>button.addEventListener('click',()=>{$(button.dataset.package).checked=true;if(button.dataset.package==='house')$('pump').checked=true;setMode('calc');updateCalc();$('calculator').scrollIntoView({behavior:'smooth'});}));
$('lead-form').addEventListener('submit',event=>{event.preventDefault();const digits=$('phone').value.replace(/\D/g,'');if(!/^[78]\d{10}$/.test(digits)){$('form-error').textContent='Введите российский номер: +7 или 8 и ещё 10 цифр.';$('phone').focus();return;}if(!$('location').value.trim()){$('form-error').textContent='Укажите населённый пункт.';$('location').focus();return;}$('form-error').textContent='';const params=$('lead-summary').value.trim()||'Параметры скважины нужно уточнить.';const text=[`Участок: ${$('location').value.trim()}`,$('name').value.trim()?`Имя: ${$('name').value.trim()}`:'',`Телефон: ${$('phone').value.trim()}`,'',params].filter(Boolean).join('\n');sendLead(event.target,text);});$('dialog-close').addEventListener('click',()=>$('lead-dialog').close());$('lead-dialog').addEventListener('click',e=>{if(e.target===$('lead-dialog')){const r=$('lead-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('lead-dialog').close();}});$('copy-lead').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('final-summary').textContent);$('copy-status').textContent='Текст скопирован.';}catch{$('copy-status').textContent='Не удалось скопировать автоматически. Выделите текст заявки и скопируйте вручную.';}});
function showContact(open){$('contact-panel').hidden=!open;$('contact-toggle').setAttribute('aria-expanded',String(open));} $('contact-toggle').addEventListener('click',()=>showContact($('contact-panel').hidden));$('contact-close').addEventListener('click',()=>showContact(false));$('contact-request').addEventListener('click',()=>showContact(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')showContact(false);});updateCalc();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_demo_estimate',title:'Настроить демонстрационный расчёт',description:'Updates the visible drilling calculator using historical 2019 rates, not a current quote. Does not submit a lead or predict depth.',inputSchema:{type:'object',properties:{depth:{type:'integer',minimum:10,maximum:200},construction:{type:'string',enum:['plastic','steel','double','seamless']},pump:{type:'boolean'},house:{type:'boolean'}},required:['depth','construction'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.depth)||input.depth<10||input.depth>200||!Object.hasOwn(rates,input.construction)||('pump'in input&&typeof input.pump!=='boolean')||('house'in input&&typeof input.house!=='boolean'))throw new Error('Invalid calculator parameters');if(input.depth>rates[input.construction].limit)throw new Error('Depth exceeds the listed construction limit');$('depth').value=input.depth;$('depth-range').value=input.depth;$('construction').value=input.construction;$('pump').checked=Boolean(input.pump);$('house').checked=Boolean(input.house);setMode('calc');updateCalc();const estimate=getEstimate();return{historicalDemo:true,priceYear:2019,minRub:estimate.min,maxRub:estimate.max,extrasQuotedSeparately:true,leadSubmitted:false};}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}

const photoDialog=document.querySelector('#photo-dialog');
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{const photo=document.querySelector('#photo-large');photo.src=button.dataset.photo;photo.alt=button.dataset.caption;document.querySelector('#photo-caption').textContent=button.dataset.caption;photoDialog.showModal()}));
document.querySelector('#photo-close').addEventListener('click',()=>photoDialog.close());
photoDialog.addEventListener('click',event=>{if(event.target===photoDialog)photoDialog.close()});

/* ==== Доработка 18.09.2026: реальная отправка заявок, «перезвоните мне», маска телефона ==== */
const DEMO=true,pageOpened=Date.now();
function goal(name){try{if(window.ym&&window.YM_ID)ym(window.YM_ID,'reachGoal',name);}catch{}}
function formatPhone(v){let d=v.replace(/\D/g,'');if(!d)return'';if(d[0]==='8')d='7'+d.slice(1);if(d[0]!=='7')d='7'+d;d=d.slice(0,11);let s='+7';if(d.length>1)s+=' ('+d.slice(1,4);if(d.length>=5)s+=') '+d.slice(4,7);if(d.length>=8)s+='-'+d.slice(7,9);if(d.length>=10)s+='-'+d.slice(9,11);return s;}
document.querySelectorAll('input[type=tel]').forEach(input=>input.addEventListener('input',()=>{const end=input.selectionStart===input.value.length;const next=formatPhone(input.value);if(end||next.length<input.value.length)input.value=next;}));
async function postLead(fields){const data=new FormData();for(const[k,v]of Object.entries(fields))if(v)data.append(k,v);data.append('_Страница',location.href);data.append('_elapsed',String(Math.round((Date.now()-pageOpened)/1000)));const response=await fetch('send.php',{method:'POST',body:data});const json=await response.json().catch(()=>({ok:false}));if(!response.ok||!json.ok)throw new Error(json.error||'delivery');}
async function sendLead(form,text){const button=form.querySelector('[type=submit]');if(form.querySelector('[name=_gotcha]').value)return;button.disabled=true;let sent=true;try{await postLead({'Телефон':$('phone').value,'Имя':$('name').value.trim(),'Участок':$('location').value.trim(),'Параметры':$('lead-summary').value.trim(),'_Форма':'Заявка с расчётом'});goal('lead');}catch{sent=false;}button.disabled=false;$('final-summary').textContent=text;$('copy-status').textContent='';$('lead-state').textContent=sent?'ЗАЯВКА ОТПРАВЛЕНА':'НЕ УДАЛОСЬ ОТПРАВИТЬ';$('lead-title').innerHTML=sent?'Спасибо!<br>Мы перезвоним.':'Связь подвела.<br>Позвоните нам.';const phone=document.querySelector('.contact-phone');$('lead-note').textContent=sent?(DEMO?'Это демонстрация: заявку получила студия «Форма сайта». Вот её текст:':'Перезвоним в рабочее время. Вот что мы получили:'):`Заявка не ушла — проверьте интернет и попробуйте ещё раз или позвоните: ${phone?phone.textContent.replace('↗','').trim():''}. Текст заявки можно скопировать:`;if(sent)form.reset();$('lead-dialog').showModal();}
$('callback-form').addEventListener('submit',async event=>{event.preventDefault();const status=$('callback-status'),digits=$('callback-phone').value.replace(/\D/g,'');status.className='';if(!/^[78]\d{10}$/.test(digits)){status.className='bad';status.textContent='Введите номер полностью: +7 и 10 цифр.';$('callback-phone').focus();return;}const button=event.target.querySelector('button');button.disabled=true;try{await postLead({'Телефон':$('callback-phone').value,'_Форма':'Перезвоните мне'});goal('callback');status.className='ok';status.textContent=DEMO?'Принято. Демо: номер получила студия «Форма сайта».':'Принято. Перезвоним в рабочее время.';event.target.reset();}catch{status.className='bad';status.textContent='Не отправилось. Проверьте интернет или позвоните нам.';}button.disabled=false;});
document.querySelectorAll('[data-open-contact]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();showContact(true);$('callback-phone').focus();}));
document.querySelectorAll('a[href^="tel:"]').forEach(link=>link.addEventListener('click',()=>goal('call')));
/* клавиатура на телефоне не должна упираться в закреплённую панель */
document.addEventListener('focusin',e=>{if(e.target.matches('input:not([type=range]):not([type=checkbox]):not([type=radio]),textarea,select'))document.body.classList.add('kbd');});
document.addEventListener('focusout',()=>document.body.classList.remove('kbd'));
/* альбомы работ: листание внутри страницы, без ухода на старый сайт */
(function(){const dialog=document.querySelector('#photo-dialog');if(!dialog||!document.querySelector('[data-album]'))return;
let list=[],at=0,title='';const img=document.querySelector('#photo-large'),cap=document.querySelector('#photo-caption');
const nav=document.createElement('div');nav.className='album-nav';nav.innerHTML='<button type="button" data-step="-1" aria-label="Предыдущее фото">‹</button><span id="album-pos"></span><button type="button" data-step="1" aria-label="Следующее фото">›</button>';dialog.append(nav);
function show(i){at=(i+list.length)%list.length;img.src=list[at];img.alt=title+', фото '+(at+1);cap.textContent=title;document.querySelector('#album-pos').textContent=(at+1)+' / '+list.length;const next=new Image();next.src=list[(at+1)%list.length];}
document.querySelectorAll('[data-album]').forEach(b=>b.addEventListener('click',e=>{e.stopImmediatePropagation();list=b.dataset.album.split(',');title=b.dataset.caption;nav.hidden=false;show(0);dialog.showModal();},true));
nav.addEventListener('click',e=>{const s=e.target.closest('[data-step]');if(s)show(at+Number(s.dataset.step));});
dialog.addEventListener('keydown',e=>{if(!list.length)return;if(e.key==='ArrowRight')show(at+1);if(e.key==='ArrowLeft')show(at-1);});
let x0=null;img.addEventListener('touchstart',e=>{x0=e.touches[0].clientX;},{passive:true});img.addEventListener('touchend',e=>{if(x0===null)return;const dx=e.changedTouches[0].clientX-x0;if(Math.abs(dx)>40)show(at+(dx<0?1:-1));x0=null;});
})();
